async function syncMasterGanisph() {
  try {
    console.log("=== SYNCHRONIZING MASTER GANISPH TABLE WITH ALL 311 PDF DATA RECORDS ===");

    // 1. Update columns schema
    await sql`ALTER TABLE master_ganisph ADD COLUMN IF NOT EXISTS company_name VARCHAR(255);`;
    await sql`ALTER TABLE master_ganisph ADD COLUMN IF NOT EXISTS assignment_type VARCHAR(50);`;
    await sql`ALTER TABLE master_ganisph ADD COLUMN IF NOT EXISTS register_active_end VARCHAR(50);`;
    await sql`ALTER TABLE master_ganisph ADD COLUMN IF NOT EXISTS assignment_active_end VARCHAR(50);`;
    await sql`ALTER TABLE master_ganisph ADD COLUMN IF NOT EXISTS regency_city VARCHAR(255);`;

    // Drop email & nik column if exists
    await sql`ALTER TABLE master_ganisph DROP COLUMN IF EXISTS email;`;
    await sql`ALTER TABLE master_ganisph DROP COLUMN IF EXISTS nik;`;

    // 2. Reset table contents
    await sql`TRUNCATE TABLE master_ganisph RESTART IDENTITY;`;

    // 3. Insert all 311 records
    let count = 0;
    for (const item of GANISPH_DATA) {
      await sql`
        INSERT INTO master_ganisph (company_name, assignment_type, name, qualification_name, registration_number, register_active_end, assignment_active_end, regency_city)
        VALUES (${item.company_name}, ${item.assignment_type}, ${item.name}, ${item.qualification_name}, ${item.registration_number}, ${item.register_active_end}, ${item.assignment_active_end}, ${item.regency_city});
      `;
      count++;
    }

    console.log(`Inserted ${count} GANISPH records successfully!`);

    // Verify sample count
    const total = await sql`SELECT COUNT(*) FROM master_ganisph;`;
    console.log("Total records in master_ganisph:", total[0].count);

  } catch (err) {
    console.error("Error syncing master_ganisph:", err);
  } finally {
    await sql.end();
  }
}

syncMasterGanisph();
